		wantIDs  []string
		wantLast []bool
	}{
		{
			name: "orchestrator and three sub-agents, sorted by ID",
			usage: agentusage.Usage{Agents: []agentusage.Agent{
				orchestrator(1, 0),
				subAgent("a03", "x", 1, 0), subAgent("a01", "x", 1, 0), subAgent("a02", "x", 1, 0),
