1	package agentusageview
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/agentusage"
9		"github.com/anthnel/devdesk/internal/ui/datatable"
10	)
11	
12	const (
13		// noModel stands for an agent whose transcript named no model.
14		noModel = "-"
15		// unknownType stands for a sub-agent whose meta file gave no type.
16		unknownType = "unknown"
17		// orchestratorLabel is the Agent cell of the main agent.
18		orchestratorLabel = "orchestrator"
19		// partialMark prefixes an output count that is a floor, not an exact value.
20		partialMark = "≥ "
21		// stem and lastStem draw the tree branch in front of a sub-agent's type.
22		stem     = "├─ "
23		lastStem = "└─ "
24	)
25	
26	// agentRow is one line of the agents table: an agent, and whether it is the
27	// last sub-agent, which decides the shape of its branch.
28	type agentRow struct {
29		agentusage.Agent
30		last bool
31	}
32	
33	// agentRows orders a session's agents: the orchestrator first, then the
34	// sub-agents by ID. The sort is stable so equal IDs keep their input order.
35	func agentRows(u agentusage.Usage) []agentRow {
36		var main, subs []agentusage.Agent
37		for _, a := range u.Agents {
38			if a.Main {
39				main = append(main, a)
40			} else {
41				subs = append(subs, a)
42			}
43		}
44		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
45	
46		rows := make([]agentRow, 0, len(u.Agents))
47		for _, a := range main {
48			rows = append(rows, agentRow{Agent: a})
49		}
50		for i, a := range subs {
51			rows = append(rows, agentRow{Agent: a, last: i == len(subs)-1})
52		}
53		return rows
54	}
55	
56	// agentColumns describes the agents table. Nothing sorts: the order is the
57	// tree. Cache columns give way first on a narrow terminal, writes before reads.
58	func agentColumns() []datatable.Column[agentRow] {
59		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
60			return datatable.Column[agentRow]{
61				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
62				Cell: func(r agentRow) string { return formatTokens(tokens(r)) },
63			}
64		}
65		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
66		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
67		cacheRead.Optional = true
68		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
69		cacheWrite.Optional, cacheWrite.DropFirst = true, true
70		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
71	
72		out := count("Out", 7, nil)
73		out.Cell = outCell
74	
75		return []datatable.Column[agentRow]{
76			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch},
77			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Cell: modelsCell, Search: modelsCell},
78			in, out, cacheRead, cacheWrite, total,
79		}
80	}
81	
82	// agentSearch is what `/` matches in the Agent column: the role and the ID,
83	// which no column shows.
84	func agentSearch(r agentRow) string { return roleCell(r) + " " + r.ID }
85	
86	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
87	// its branch.
88	func roleCell(r agentRow) string {
89		if r.Main {
90			return orchestratorLabel
91		}
92		typ := r.Type
93		if typ == "" {
94			typ = unknownType
95		}
96		if r.last {
97			return lastStem + typ
98		}
99		return stem + typ
100	}
101	
102	// modelsCell lists the models the agent used.
103	func modelsCell(r agentRow) string {
104		if len(r.Models) == 0 {
105			return noModel
106		}
107		return strings.Join(r.Models, ", ")
108	}
109	
110	// outCell is the output count. A sub-agent still being written is a floor and
111	// says so; the orchestrator never does, its transcript is the one being read.
112	func outCell(r agentRow) string {
113		out := formatTokens(r.Tokens.Output)
114		if !r.Main && r.PartialOutput() {
115			return partialMark + out
116		}
117		return out
118	}
119	
120	// formatTokens renders a count compactly, floored to one decimal: 1099 is
121	// "1.0k", never "1.1k". From 100k up the decimal is dropped.
122	func formatTokens(n int64) string {
123		units := []struct {
124			size   int64
125			suffix string
126		}{
127			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
128		}
129		for _, u := range units {
130			if n < u.size {
131				continue
132			}
133			tenths := n / (u.size / 10) // divide first: n*10 would overflow
134			if u.suffix == "k" && tenths >= 1000 {
135				return fmt.Sprintf("%dk", tenths/10)
136			}
137			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
138		}
139		return fmt.Sprintf("%d", n)
140	}
141

